SELECT 
FROM exam_info e
LEFT JOIN paper_info p ON e.paper_id = p.paper_id


        AND e.exam_name LIKE CONCAT('%', #{examNameFuzzy}, '%')


        AND e.grade = #{grade}


        AND e.paper_id = #{paperId}


        AND e.status = #{status}


ORDER BY e.create_time DESC

    LIMIT #{simplePage.start}, #{simplePage.end}

SELECT COUNT(1) FROM exam_info e


        AND e.exam_name LIKE CONCAT('%', #{examNameFuzzy}, '%')


        AND e.grade = #{grade}


        AND e.paper_id = #{paperId}


        AND e.status = #{status}

