UPDATE exam_info
exam_name = #{examName}, stage = #{stage}, grade = #{grade}, paper_id = #{paperId}, start_time = #{startTime}, end_time = #{endTime}, duration_minutes = #{durationMinutes}, status = #{status}, update_time = #{updateTime},
WHERE exam_id = #{examId}
